package com.simon.mytasks;import android.app.Activity;import androidx.window.extensions.WindowExtensionsProvider;public class ComposerWindowObserverTest{public static void main(String[] x){final int[] callbacks={0};ComposerWindowObserver o=new ComposerWindowObserver(new Activity(),bounds->{if(bounds.size()!=1||bounds.get(0).height()!=20)throw new AssertionError("actual occlusion not fold line");callbacks[0]++;});o.start();WindowExtensionsProvider.Component c=WindowExtensionsProvider.extensions.component;if(c.consumer==null)throw new AssertionError("listener not registered");c.consumer.accept(new WindowExtensionsProvider.Info());o.stop();if(c.consumer!=null||c.removed==null)throw new AssertionError("listener leaked");c.removed.accept(new WindowExtensionsProvider.Info());if(callbacks[0]!=1)throw new AssertionError("late lifecycle callback applied");System.out.println("ComposerWindowObserverTest passed: reflective OEM Java Consumer + lifecycle fence");}}